mapper.codeEditorJavascript:
// Módulo 1: dispositivos novedosos FDA (PMA originales + De Novo)
// input.month_override: "AAAA-MM" opcional; por defecto, mes anterior al actual
const pad = n => String(n).padStart(2, '0');
const now = new Date();
let y, m;
if (input.month_override && /^\d{4}-\d{2}$/.test(input.month_override)) {
  [y, m] = input.month_override.split('-').map(Number);
} else {
  const d = new Date(Date.UTC(now.getUTCFullYear(), now.getUTCMonth() - 1, 1));
  y = d.getUTCFullYear(); m = d.getUTCMonth() + 1;
}
const ym = (yy, mm) => { const d = new Date(Date.UTC(yy, mm - 1, 1)); return [d.getUTCFullYear(), d.getUTCMonth() + 1]; };
const lastDay = (yy, mm) => new Date(Date.UTC(yy, mm, 0)).getUTCDate();
const month = `${y}-${pad(m)}`;
const [py, pm] = ym(y, m - 1);
const [by, bm] = ym(y, m - 36);
const freshFrom = `${py}${pad(pm)}01`, to = `${y}${pad(m)}${pad(lastDay(y, m))}`;
const backFrom = `${by}${pad(bm)}01`;

async function q(path) {
  const r = await fetch('https://api.fda.gov/device/' + path);
  const j = await r.json();
  if (j.error && j.error.code === 'NOT_FOUND') return { results: [], meta: {} };
  if (!r.ok) throw new Error('openFDA ' + r.status + ' ' + JSON.stringify(j.error));
  return j;
}
const [pma, den] = await Promise.all([
  q(`pma.json?search=decision_date:[${backFrom}+TO+${to}]+AND+supplement_number:""&limit=1000`),
  q(`510k.json?search=k_number:DEN*+AND+decision_date:[${backFrom}+TO+${to}]&limit=1000`)
]);
const devs = [];
for (const x of pma.results || []) {
  if (x.decision_code && x.decision_code !== 'APPR') continue;
  devs.push({ id: x.pma_number, pathway: 'PMA', name: x.trade_name || x.generic_name || '', generic: x.generic_name || '', applicant: x.applicant || '', date: x.decision_date, specialty: x.advisory_committee_description || '' });
}
for (const x of den.results || []) {
  if (x.decision_code && !/^DEN/.test(x.decision_code)) continue;
  devs.push({ id: x.k_number, pathway: 'De Novo', name: x.device_name || '', generic: '', applicant: x.applicant || '', date: x.decision_date, specialty: x.advisory_committee_description || '' });
}
const freshStart = `${py}-${pad(pm)}-01`;
for (const d of devs) d.fresh = d.date >= freshStart;
return {
  month,
  fresh_window: `${freshStart} a ${y}-${pad(m)}-${pad(lastDay(y, m))}`,
  fda_last_updated: (pma.meta && pma.meta.last_updated) || '',
  n_fresh: devs.filter(d => d.fresh).length,
  n_backlog: devs.length,
  devices_json: JSON.stringify(devs)
};

// Módulo 4: matching contra ANVISA (CSV) — salida para revisión humana
const TS = Date.now(); const lap = {};
const devs = JSON.parse(input.devices_json || '[]');
const month = input.month; // AAAA-MM
const csv = input.csv || '';
if (csv.length < 1000000) throw new Error('CSV ANVISA vacío o truncado: ' + csv.length + ' caracteres');

const norm = s => (s || '').toUpperCase().normalize('NFD').replace(/[̀-ͯ]/g, '').replace(/�/g, '').replace(/[®™©]/g, ' ');
const STOP = new Set(('SYSTEM SYSTEMS DEVICE DEVICES KIT CATHETER CATHETERS DELIVERY VALVE REPLACEMENT MONITOR MONITORING TEST ASSAY ' +
  'THE AND FOR WITH OF MODEL DX ANALYSIS SENSOR SET TOOL TOOLS PTCA DRUG ELUTING BALLOON STENT SCAFFOLD IMPLANT IMPLANTABLE ' +
  'PROSTHESIS DISC CERVICAL LENS CONTACT AI ECG CONTINUOUS GLUCOSE DAY SOFTWARE TRANSCATHETER TRICUSPID MITRAL AORTIC PULSED FIELD ' +
  'ABLATION GUIDE STEERABLE SURGICAL ROBOTIC AUTOMATED MANAGEMENT STOOL DUAL KETONE PLUS PRO MINI MAX NEW GEN SYSTEMA SISTEMA ' +
  'OVERNIGHT ORTHOKERATOLOGY DEPLOYMENT RESORBABLE EVEROLIMUS VASCULAR CORONARY PERIPHERAL HOME USE KIT PANEL DETECTION').split(/\s+/));
const CORP = new Set('INC INC. LLC LTD LIMITED CORP CORPORATION CO COMPANY GMBH SA S.A. AG BV PLC THE MEDICAL MEDICALS TECHNOLOGY TECHNOLOGIES USA US HEALTH HEALTHCARE LIFE SCIENCES BIOSCIENCES SURGICAL'.split(' '));

function brandKey(name, applicant) {
  const n = norm(name).replace(/\(.*?\)/g, ' ');
  const own = new Set(norm(applicant).split(/[^A-Z0-9]+/));
  const toks = n.split(/[^A-Z0-9-]+/).map(t => t.replace(/^-+|-+$/g, '').replace(/^(.{3,})TM$/, '$1')).filter(Boolean);
  const cand = toks.filter(t => t.length >= 3 && !STOP.has(t) && !own.has(t) && !/^\d+$/.test(t) && !/^(G|S|V)\d+$/.test(t));
  return cand[0] || '';
}
function mfrKey(app) {
  const all = norm(app).split(/[^A-Z0-9]+/).filter(Boolean);
  const toks = all.filter(t => t.length >= 3 && !CORP.has(t));
  return toks[0] || all.filter(t => t.length >= 2 && !CORP.has(t))[0] || '';
}
const esc = s => s.replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
const wordRe = k => new RegExp('(^|[^A-Z0-9])' + esc(k) + '($|[^A-Z0-9])');
// marcas de 6+ letras también matchean como prefijo (ej. BAGUERA en "BAGUERAc")
const brandRe = k => k.length >= 6 ? new RegExp('(^|[^A-Z0-9])' + esc(k)) : wordRe(k);
const toISO = s => { const mm = (s || '').match(/(\d\d)\/(\d\d)\/(\d{4})/); return mm ? `${mm[3]}-${mm[2]}-${mm[1]}` : ''; };
const months = (a, b) => Math.round(((new Date(b) - new Date(a)) / 86400000 / 30.44) * 10) / 10;

// --- ANVISA: recorrer el CSV sin partirlo entero (límite de memoria del sandbox) y
// quedarse solo con filas cuyo NOME_COMERCIAL contiene alguna marca buscada
const BKS = new Set(devs.map(d => brandKey(d.name, d.applicant)).filter(Boolean));
const tokensOf = s => { const out = new Set(); for (const w of s.split(/[^A-Z0-9-]+/)) { for (const t of [w, w.replace(/^-+|-+$/g, '')]) { if (t.length < 3) continue; out.add(t); for (let n = 6; n < t.length; n++) out.add(t.slice(0, n)); } } return out; };
let p = csv.indexOf('\n');
const H = csv.slice(0, p).replace(/\r/g, '').split(';');
const ix = k => H.indexOf(k);
const iReg = ix('NUMERO_REGISTRO_CADASTRO'), iNom = ix('NOME_COMERCIAL'), iCls = ix('CLASSE_RISCO'),
  iDet = ix('DETENTOR_REGISTRO_CADASTRO'), iFab = ix('NOME_FABRICANTE'), iDt = ix('DT_PUB_REGISTRO_CADASTRO');
if ([iReg, iNom, iDet, iFab, iDt].some(i => i < 0)) throw new Error('Cambió el formato del CSV ANVISA: ' + H.join('|'));
const up = s => (s || '').toUpperCase().replace(/�/g, '');
const regs = new Map(); const allRegs = new Set(); let nLines = 0;
while (p >= 0 && p < csv.length) {
  const q = csv.indexOf('\n', p + 1); const line = csv.slice(p + 1, q < 0 ? csv.length : q); p = q;
  if (!line) continue; nLines++;
  const c = line.split(';'); if (c.length < H.length - 1) continue;
  allRegs.add(c[iReg]);
  const nome = up(c[iNom]); let hit = false;
  for (const t of tokensOf(nome)) if (BKS.has(t)) { hit = true; break; }
  if (!hit) continue;
  const k = c[iReg]; let r = regs.get(k);
  if (!r) { r = { reg: k, nome, cls: c[iCls], det: up(c[iDet]), fab: '', date: toISO(c[iDt]) }; regs.set(k, r); }
  if (c[iFab]) r.fab += ' ' + up(c[iFab]);
}
if (nLines < 50000) throw new Error('CSV ANVISA con pocas filas: ' + nLines);
lap.parse = Date.now() - TS;
const REGS = [...regs.values()];
const NREGS = allRegs.size;
const IDX = new Map();
for (const r of REGS) for (const t of tokensOf(r.nome)) { let a = IDX.get(t); if (!a) IDX.set(t, a = []); a.push(r); }
const byToken = k => IDX.get(k) || [];
lap.index = Date.now() - TS; lap.kept = REGS.length;

function anvisa(d) {
  const bk = brandKey(d.name, d.applicant), mk = mfrKey(d.applicant);
  if (!bk) return { status: 'Revisar', ev: 'Sin token de marca; buscar a mano', bk, mk, hits: [] };
  const re = brandRe(bk), mre = mk ? wordRe(mk) : null;
  const brand = byToken(bk).filter(r => re.test(r.nome));
  const strong = brand.filter(r => mre && (mre.test(r.fab) || mre.test(r.det)));
  const fmt = r => `${r.reg} | ${r.nome.slice(0, 90)} | fab: ${r.fab.trim().slice(0, 60)} | clase ${r.cls} | ${r.date}`;
  if (strong.length) {
    strong.sort((a, b) => a.date.localeCompare(b.date));
    const before = strong.filter(r => r.date && r.date < d.date);
    const after = strong.filter(r => r.date && r.date >= d.date);
    const pick = after[0] || strong[0];
    const status = before.length ? 'Revisar' : 'Encontrado';
    let ev = strong.slice(0, 5).map(fmt).join('\n');
    if (before.length) ev = `OJO: ${before.length} registro(s) anterior(es) a la FDA (posible generación previa o aprobación CE primero).\n` + ev;
    return { status, ev, bk, mk, hits: strong, pick };
  }
  if (brand.length) return { status: 'Revisar', ev: 'Marca coincide pero fabricante no:\n' + brand.slice(0, 5).map(fmt).join('\n'), bk, mk, hits: [] };
  return { status: 'No encontrado', ev: `Sin coincidencias para "${bk}" en ${NREGS} registros ANVISA`, bk, mk, hits: [] };
}

const out = [];
const fresh = devs.filter(d => d.fresh);
fresh.forEach((d, i) => {
  const a = anvisa(d);
  out.push({
    Device: d.name, Key: `${d.id}|Nuevo FDA`, Run_Month: d.date.slice(0, 7), Row_Type: 'Nuevo FDA', FDA_ID: d.id, Pathway: d.pathway,
    Applicant: d.applicant, FDA_Decision_Date: d.date, Specialty: d.specialty, Brand_Key: `${a.bk} / ${a.mk}`,
    BR_Status: a.status, BR_Reg_Number: a.pick ? a.pick.reg : '', BR_Reg_Date: a.pick ? a.pick.date : '',
    Lag_BR_Months: a.pick && a.status === 'Encontrado' ? months(d.date, a.pick.date) : '',
    BR_Evidence: a.ev, _bk: a.bk, _mk: a.mk
  });
});
// Llegadas a Brasil en el mes, de dispositivos FDA de los últimos 36 meses
for (const d of devs.filter(x => !x.fresh)) {
  const a = anvisa(d);
  if (!a.hits.length) continue;
  const arrivals = a.hits.filter(r => r.date.slice(0, 7) === month);
  for (const r of arrivals) {
    const prior = a.hits.filter(h => h.date && h.date < r.date);
    if (prior.length > 10) continue; // marca paraguas (plataforma con decenas de registros): ruido, no es el dispositivo FDA
    out.push({
      Device: d.name, Key: `${d.id}|${r.reg}|Llegó a Brasil`, Run_Month: month, Row_Type: 'Llegó a Brasil', FDA_ID: d.id, Pathway: d.pathway,
      Applicant: d.applicant, FDA_Decision_Date: d.date, Specialty: d.specialty, Brand_Key: `${a.bk} / ${a.mk}`,
      BR_Status: prior.length || r.date < d.date ? 'Revisar' : 'Encontrado', BR_Reg_Number: r.reg, BR_Reg_Date: r.date,
      Lag_BR_Months: prior.length || r.date < d.date ? '' : months(d.date, r.date),
      BR_Evidence: (prior.length ? `OJO: ya había ${prior.length} registro(s) previo(s) con esta marca: ${prior.slice(0, 3).map(h => h.reg + ' ' + h.date).join(', ')}\n` : '') +
        `${r.reg} | ${r.nome.slice(0, 90)} | fab: ${r.fab.trim().slice(0, 60)} | clase ${r.cls} | ${r.date}`,
      CO_Status: '', CO_Evidence: ''
    });
  }
}
// Consultas INVIMA para los nuevos (las hace Make con módulos HTTP); siempre hay una fila dummy para que la cadena siga
const queries = [{ key: '_dummy', bk: 'ZZZZQQQQ' }].concat(out.filter(r => r.Row_Type === 'Nuevo FDA' && r._bk).map(r => ({ key: r.Key, bk: r._bk })));

return { n_candidates: out.length, n_anvisa_regs: NREGS, lap: JSON.stringify(lap), rows_json: JSON.stringify(out), queries };

// Módulo 8: clasificar INVIMA, deduplicar contra Airtable y armar lotes
const norm = s => (s || '').toUpperCase().normalize('NFD').replace(/[̀-ͯ]/g, '').replace(/�/g, '').replace(/[®™©]/g, ' ');
const esc = s => s.replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
const wordRe = k => new RegExp('(^|[^A-Z0-9])' + esc(k) + '($|[^A-Z0-9])');
const brandRe = k => k.length >= 6 ? new RegExp('(^|[^A-Z0-9])' + esc(k)) : wordRe(k);
const rows = JSON.parse(input.rows_json || '[]');
const raw = String(input.invima || '');
const resp = new Map();
for (const chunk of raw.split('@@@')) {
  const k = chunk.indexOf('|||'); if (k < 0) continue;
  resp.set(chunk.slice(0, k).trim(), chunk.slice(k + 3));
}
function classify(bk, mk, txt, fdaDate) {
  let data; try { data = JSON.parse(txt); } catch (e) { return { status: 'Revisar', ev: 'INVIMA no respondió o respuesta inválida; revisar a mano' }; }
  if (!Array.isArray(data)) return { status: 'Revisar', ev: 'Error API INVIMA: ' + String(txt).slice(0, 200) };
  const re = brandRe(bk), mre = mk ? wordRe(mk) : null;
  const b = data.filter(x => re.test(norm(x.prodcuto)) || re.test(norm(x.marca)));
  const byExp = new Map();
  for (const x of b) { const e = byExp.get(x.expediente) || { ...x, roles: '' }; e.roles += ' ' + norm(x.nombre_rol) + ' ' + norm(x.titular); byExp.set(x.expediente, e); }
  const exps = [...byExp.values()];
  const strong = exps.filter(x => mre && mre.test(x.roles));
  const fmt = x => `${x.registro_sanitario} | ${x.estado_registro} | ${norm(x.prodcuto).slice(0, 80)} | titular: ${norm(x.titular).slice(0, 50)} | riesgo ${x.nivel_riesgo}`;
  if (strong.length) {
    const st = strong.some(x => /VIGENTE/i.test(x.estado_registro)) ? 'Vigente' : strong.some(x => /ESTUDIO|TRAMITE/i.test(norm(x.estado_registro))) ? 'En trámite' : 'Revisar';
    const fy = Number(String(fdaDate || '').slice(0, 4));
    const old = strong.filter(x => { const mm = String(x.registro_sanitario || '').match(/(\d{4})DM/); return mm && fy && Number(mm[1]) < fy; });
    const warn = old.length ? `OJO: ${old.length} registro(s) con año anterior a la aprobación FDA (posible generación previa, otro producto de la marca o aprobación CE primero).\n` : '';
    return { status: old.length ? 'Revisar' : st, ev: warn + strong.slice(0, 5).map(fmt).join('\n') + '\n(INVIMA no publica fecha de otorgamiento)' };
  }
  if (exps.length) return { status: 'Revisar', ev: 'Marca coincide pero titular/fabricante no:\n' + exps.slice(0, 5).map(fmt).join('\n') };
  return { status: 'No encontrado', ev: `Sin coincidencias para "${bk}" en INVIMA` };
}
for (const r of rows) {
  if (r.Row_Type === 'Nuevo FDA') {
    if (!r._bk) { r.CO_Status = 'Revisar'; r.CO_Evidence = 'Sin token de marca'; }
    else { const c = classify(r._bk, r._mk, resp.has(r.Key) ? resp.get(r.Key) : '', r.FDA_Decision_Date); r.CO_Status = c.status; r.CO_Evidence = c.ev; }
  }
  delete r._bk; delete r._mk;
}
// Duplicado semántico: el mismo registro ANVISA asignado a más de un dispositivo FDA en esta corrida
const regCount = {};
for (const r of rows) if (r.BR_Reg_Number) regCount[r.BR_Reg_Number] = (regCount[r.BR_Reg_Number] || 0) + 1;
for (const r of rows) if (r.BR_Reg_Number && regCount[r.BR_Reg_Number] > 1) {
  r.BR_Status = 'Revisar'; r.Lag_BR_Months = '';
  r.BR_Evidence = `OJO: el registro ANVISA ${r.BR_Reg_Number} quedó asignado a ${regCount[r.BR_Reg_Number]} dispositivos FDA distintos; probablemente es otro producto de la marca.\n` + (r.BR_Evidence || '');
}
let existing = input.existing;
if (typeof existing === 'string') { try { existing = JSON.parse(existing); } catch (e) { existing = []; } }
if (Array.isArray(existing) && existing.length >= 100) throw new Error('Airtable devolvió 100+ keys para dedupe: ampliar el control antes de cargar (riesgo de duplicados)');
const have = new Set((Array.isArray(existing) ? existing : []).map(r => r && r.fields && r.fields.Key).filter(Boolean));
const fresh_rows = rows.filter(r => !have.has(r.Key)).map(r => {
  const f = { ...r, Review: 'Pendiente' };
  for (const k of Object.keys(f)) if (f[k] === '' || f[k] === null || f[k] === undefined) delete f[k];
  return f;
});
const batches = [];
for (let i = 0; i < fresh_rows.length; i += 10) batches.push(JSON.stringify({ typecast: true, records: fresh_rows.slice(i, i + 10).map(fields => ({ fields })) }));
return { n_rows: rows.length, n_new: fresh_rows.length, n_skipped_existing: rows.length - fresh_rows.length, n_invima_resp: resp.size, batches };
